/* PULS 14: diary slides, nutrient snapshots and focused workout flow. */
const nutrientLabels={fiber:['Ballaststoffe','g'],vitc:['Vitamin C','mg'],iron:['Eisen','mg'],calcium:['Calcium','mg'],b12:['Vitamin B12','µg'],folate:['Folat','µg'],potassium:['Kalium','mg'],magnesium:['Magnesium','mg']};
function validNutrients(x){return x===undefined||x&&typeof x==='object'&&!Array.isArray(x)&&Object.entries(x).every(([k,v])=>['water',...Object.keys(nutrientLabels)].includes(k)&&typeof v==='number'&&Number.isFinite(v)&&v>=0&&v<=1e9)}
function nutrientTotals(){let items=state.foods.filter(x=>x.date===date),totals={},coverage={};for(let key of ['water',...Object.keys(nutrientLabels)]){totals[key]=0;coverage[key]=0;for(let x of items)if(Number.isFinite(x.nutrients?.[key])){totals[key]+=x.nutrients[key];coverage[key]++}}return {totals,coverage,count:items.length,unknownDrinks:items.filter(x=>x.unit==='ml'&&!Number.isFinite(x.nutrients?.water)).length}}
let nutrientSlide=0;
function macroProgress(key,label,color){let t=totals(),g=state.goals[key]||0,value=t[key];return `<div class="slideprogress"><div><span>${label}</span><strong>${n(value)} / ${n(g)} ${key==='kcal'?'kcal':'g'}</strong></div><div class="bar"><i style="width:${g?Math.min(100,value/g*100):0}%;background:${color}"></i></div><small>${value>g?'Über Ziel: '+n(value-g):'Noch offen: '+n(g-value)} ${key==='kcal'?'kcal':'g'}</small></div>`}
function nutritionSlides(){let t=totals(),nt=nutrientTotals();return `<section class="nutritiondeck"><div class="nutritiontrack" id="nutrition-track" onscroll="nutritionSlideChanged(this)"><article class="nutritionslide"><div class="cardhead"><h2>Energie</h2><small>Tagesüberblick</small></div><div class="energydials">${[['Gegessen',t.kcal],['Dein Ziel',state.goals.kcal],['Noch offen',Math.max(0,state.goals.kcal-t.kcal)]].map(([label,value])=>`<div><div class="energydial"><strong>${n(Math.round(value))}</strong><small>kcal</small></div><span>${label}</span></div>`).join('')}</div><p class="note">Dein eingestelltes Kalorienziel. Kein gemessener Energieverbrauch.</p></article><article class="nutritionslide"><h2>Energie & Makros</h2>${macroProgress('kcal','Energie','#f5ac84')}${macroProgress('p','Protein','#8bd4a0')}${macroProgress('c','Kohlenhydrate','#81cbdc')}${macroProgress('f','Fett','var(--lime)')}</article><article class="nutritionslide"><div class="cardhead"><h2>Mikronährstoffe</h2><button class="textbtn" onclick="microTargetForm()">Ziele</button></div><div class="microgrid">${Object.entries(nutrientLabels).map(([key,[label,unit]])=>{let target=state.microGoals?.[key];return `<div><span>${label}</span><strong>${nt.coverage[key]?n(round(nt.totals[key]))+' '+unit:'Unbekannt'}</strong>${target?`<div class="bar"><i style="width:${Math.min(100,nt.totals[key]/target*100)}%;background:var(--lime)"></i></div><small>Ziel ${n(target)} ${unit}</small>`:''}<small>${nt.coverage[key]} / ${nt.count} Einträge mit Wert</small></div>`}).join('')}</div><p class="note">Unvollständige erfasste Summe. Fehlende Werte zählen nicht als null; alte Einträge ohne Nährstoffdaten sind nicht rückwirkend ergänzt.</p></article></div><div class="slidedots">${['Energie','Makros','Mikros'].map((s,i)=>`<button aria-label="${s} anzeigen" class="${nutrientSlide===i?'selected':''}" onclick="setNutrientSlide(${i})"></button>`).join('')}</div></section>`}
function setNutrientSlide(i){nutrientSlide=i;let track=$('nutrition-track');if(track)track.scrollTo({left:i*track.clientWidth,behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}
function syncNutritionHeight(track){let pane=track?.children?.[nutrientSlide];if(pane)track.style.height=pane.offsetHeight+'px'}
function nutritionSlideChanged(track){nutrientSlide=Math.max(0,Math.min(2,Math.round(track.scrollLeft/Math.max(1,track.clientWidth))));document.querySelectorAll('.slidedots button').forEach((el,i)=>el.classList.toggle('selected',i===nutrientSlide));syncNutritionHeight(track)}
function microTargetForm(){openModal('Eigene Nährstoffziele',`<form onsubmit="saveMicroTargets(event)"><p class="note">Optional: Trage deine eigenen Tagesziele ein. Leer lassen bedeutet kein Ziel.</p><div class="formgrid">${Object.entries(nutrientLabels).map(([key,[label,unit]])=>`<label>${label} · ${unit}<input id="micro-${key}" type="number" min="0" max="1000000" step="any" value="${state.microGoals?.[key]||''}"></label>`).join('')}</div><button class="btn full">Ziele speichern</button></form>`)}
function saveMicroTargets(event){event.preventDefault();let goals={};for(let key of Object.keys(nutrientLabels)){let v=+$('micro-'+key).value;if(!Number.isFinite(v)||v<0||v>1e6){toast('Bitte gültige Zielwerte eingeben');return}if(v>0)goals[key]=v}state.microGoals=goals;save();modal.close();render()}
function waterCard(){let nt=nutrientTotals(),goal=state.waterGoal||0;return `<section class="card watercard"><div class="cardhead"><h3>💧 Gesamtwasser</h3><button class="textbtn" onclick="waterForm()">＋ Wasser</button></div><div class="watertotal"><strong>${n(Math.round(nt.totals.water))} ml</strong><button class="textbtn" onclick="waterGoalForm()">${goal?'Ziel '+n(goal)+' ml':'Eigenes Ziel setzen'}</button></div>${goal?`<div class="bar"><i style="width:${Math.min(100,nt.totals.water/goal*100)}%;background:#81cbdc"></i></div>`:''}<p class="note">Bekannter Wasseranteil aus Lebensmitteln und Getränken (1 g Wasser ≈ 1 ml). ${nt.coverage.water} / ${nt.count} Einträge mit Wasserwert.${nt.unknownDrinks?' '+nt.unknownDrinks+' Getränke ohne Wasserwert sind noch nicht enthalten.':''}</p></section>`}
function waterForm(){openModal('Wasser erfassen',`<form onsubmit="logWater(event)"><label>Getrunkenes Wasser · ml<input id="water-amount" type="number" inputmode="decimal" min="1" max="10000" step="1" value="250" required></label><button class="btn full">Wasser hinzufügen</button></form>`)}
function logWater(event){event.preventDefault();let amount=+$('water-amount').value;if(!(amount>0&&amount<=10000))return;state.foods.push({id:uid(),date,meal:'Snacks',name:'Trinkwasser',grams:amount,unit:'ml',kcal:0,p:0,c:0,f:0,nutrients:{water:amount}});save();modal.close();render();toast('Wasser erfasst')}
function waterGoalForm(){openModal('Dein Wasserziel',`<form onsubmit="event.preventDefault();let v=+$('water-goal').value;if(v>=0&&v<=10000){state.waterGoal=v;save();modal.close();render()}"><label>Eigenes Tagesziel · ml (0 = ohne Ziel)<input id="water-goal" type="number" min="0" max="10000" step="1" value="${state.waterGoal||0}" required></label><button class="btn full">Speichern</button></form>`)}
function compactDiary(){let items=state.foods.filter(x=>x.date===date);return `<section class="card compactdiary"><div class="cardhead"><h3>Dein Essen</h3><span class="badge">${items.length}</span></div>${items.map(x=>`<button class="diaryrow" onclick="editDiaryFood('${x.id}')"><span><strong>${esc(x.name)}</strong><small>${n(x.grams)} ${x.unit==='ml'?'ml':'g'}</small></span><span>${n(Math.round(x.kcal))}<small>kcal</small></span></button>`).join('')||'<p class="empty">Noch nichts erfasst. Tippe unten auf ＋.</p>'}</section>`}
function nutrientDetails(){let nt=nutrientTotals();return `<details class="card nutrientdetails"><summary>Mikronährstoffe & Ballaststoffe</summary><div class="cardhead"><p class="note">Erfasste Nährwerte dieses Tages</p><button class="textbtn" onclick="microTargetForm()">Ziele einstellen</button></div><div class="microgrid">${Object.entries(nutrientLabels).map(([key,[label,unit]])=>{let target=state.microGoals?.[key];return `<div><span>${label}</span><strong>${nt.coverage[key]?n(round(nt.totals[key]))+' '+unit:'Unbekannt'}</strong>${target?`<div class="bar"><i style="width:${Math.min(100,nt.totals[key]/target*100)}%;background:var(--lime)"></i></div><small>Ziel ${n(target)} ${unit}</small>`:''}<small>${nt.coverage[key]} / ${nt.count} Einträge mit Wert</small></div>`}).join('')}</div><p class="note">Summe bekannter Werte. Fehlende Nährstoffangaben sind nicht enthalten.</p></details>`}
home=function(){return `<div class="dashboardstack">${macroCard()}<button class="btn full mainaction" onclick="foodForm();foodTab('search')">＋ Essen eintragen</button>${todayFoodList()}${quickTraining()}${progressChart()}</div>`};
nutrition=function(){return `<div class="dashboardstack"><div class="actionrow"><button class="btn" onclick="foodForm();foodTab('search')">＋ Essen hinzufügen</button><button class="btn secondary" onclick="foodForm();foodTab('barcode')">Barcode scannen</button><button class="btn secondary" onclick="foodForm();foodTab('recipes')">Meine Rezepte</button></div>${waterCard()}${compactDiary()}${nutrientDetails()}${foodSuggestionCard()}${productAttribution}</div>`};
/* Snapshot nutrients into diary records so edits to products never alter old entries. */
const flowSelectFood=selectFood;selectFood=function(id){flowSelectFood(id);if(foodSelection?.unit==='ml'&&$('grams')){$('foodbody').insertAdjacentHTML('beforeend',`<label>Wasseranteil · ml je 100 ml (optional)<input id="drink-water" type="number" min="0" max="100" step="0.1" value="${foodSelection.nutrients?.water??''}" placeholder="Unbekannt" oninput="setDrinkWater(this.value)"></label><p class="note">Nur einen bekannten Wasseranteil eintragen. Unbekannte Getränke werden nicht pauschal als 100 % Wasser gewertet.</p>`)} };
function setDrinkWater(value){if(!foodSelection)return;if(value===''){if(foodSelection.nutrients)delete foodSelection.nutrients.water;save();return}let v=+value;if(Number.isFinite(v)&&v>=0&&v<=100){foodSelection.nutrients??={};foodSelection.nutrients.water=v;save()}}
const flowAddFood=addFood;addFood=function(event){let count=state.foods.length,selection=foodSelection,amount=Number($('grams')?.value),snapshot={};for(let [key,value] of Object.entries(selection?.nutrients||{}))if(Number.isFinite(value))snapshot[key]=value*amount/100;flowAddFood(event);if(state.foods.length>count&&Object.keys(snapshot).length){state.foods.at(-1).nutrients=snapshot;save();render()}};
const flowSaveAmount=saveDiaryAmount;saveDiaryAmount=function(event,id){let x=state.foods.find(x=>x.id===id),before=x?.grams,amount=+$('diary-amount').value;flowSaveAmount(event,id);if(x&&before>0&&x.grams===amount&&x.nutrients){for(let k of Object.keys(x.nutrients))x.nutrients[k]*=amount/before;save();render()}};
const flowEditDiary=editDiaryFood;editDiaryFood=function(id){flowEditDiary(id);$('mb').insertAdjacentHTML('beforeend',`<button class="textbtn full" onclick="removeEntry('foods','${id}')">Eintrag löschen</button>`)};
/* All entry dialogs become sheets on phones; a fresh open resets scroll. */
const flowOpenModal=openModal;openModal=function(title,body){flowOpenModal(title,body);modal.scrollTop=0};
let sessionWorkoutId=null,completionId=null,completionStep=0;
function sessionRoot(){let root=$('session-root');if(!root){root=document.createElement('section');root.id='session-root';root.tabIndex=-1;root.setAttribute('role','dialog');root.setAttribute('aria-modal','true');root.setAttribute('aria-label','Training');document.body.appendChild(root)}return root}
function openWorkoutSession(id){let w=state.workouts.find(w=>w.id===id&&!w.finished);if(!w)return;sessionWorkoutId=id;completionId=null;modal.close();render()}
function minimizeSession(){sessionWorkoutId=null;completionId=null;render()}
function renderWorkoutSession(){document.querySelectorAll('main,aside').forEach(el=>el.inert=!!(sessionWorkoutId||completionId));let root=$('session-root');if(!sessionWorkoutId&&!completionId){if(root)root.remove();document.body.classList.remove('sessionopen');return}root=sessionRoot();document.body.classList.add('sessionopen');if(completionId){root.innerHTML=completionHtml(completionId,completionStep);root.scrollTop=0;return}let w=state.workouts.find(x=>x.id===sessionWorkoutId&&!x.finished);if(!w){sessionWorkoutId=null;renderWorkoutSession();return}root.innerHTML=`<header class="sessionhead"><button class="quiet" aria-label="Workout minimieren" onclick="minimizeSession()">⌄</button><strong data-workout-clock="${w.id}">${formatClock(elapsedWorkout(w)||0)}</strong><button class="btn" onclick="finishWorkout('${w.id}')">Beenden →</button></header><div class="sessioncontent"><h2>${esc(w.name)}</h2>${restCard(w)}${w.exercises.map((e,i)=>exerciseCard(w,e,i)).join('')}<button class="btn full" onclick="exerciseForm('${w.id}')">＋ Übung hinzufügen</button></div>`}
const flowStartRoutine=startRoutine;startRoutine=function(id){flowStartRoutine(id);let w=activeWorkout();if(w)openWorkoutSession(w.id)};
const flowStartEmpty=startEmptyWorkout;startEmptyWorkout=function(event){flowStartEmpty(event);let w=activeWorkout();if(w)openWorkoutSession(w.id)};
const flowExerciseCard=exerciseCard;exerciseCard=function(w,e,i){return flowExerciseCard(w,e,i).replace('class="textbtn" onclick="addSet','class="btn secondary full addsetwide" onclick="addSet')};
const flowWorkoutCard=workoutCard;workoutCard=function(w){if(w.finished)return flowWorkoutCard(w);return `<section class="card"><div class="cardhead"><h2>${esc(w.name)}</h2><span class="badge">Läuft</span></div><p>${w.exercises.length} Übungen · ${loggedSets(w).length} Sätze erledigt</p><button class="btn full" onclick="openWorkoutSession('${w.id}')">Workout öffnen →</button></section>`};
routinesPage=function(){return `<div class="sectionhead"><h2>Meine Routinen</h2><button class="btn" onclick="routineForm()">＋ Routine</button></div>${state.routines.map(r=>`<section class="card routinepreview"><div class="cardhead"><div><h2>${esc(r.name)}</h2><small>${r.exercises.reduce((a,e)=>a+e.sets,0)} Sätze · ${r.exercises.length} Übungen</small></div><button class="textbtn" onclick="routineForm('${r.id}')">Bearbeiten</button></div>${r.exercises.slice(0,3).map(e=>`<div class="routinepreviewrow"><span>${esc(exerciseBookItem(e.exerciseId)?.name||'Übung')}</span><small>${e.sets} Sätze</small></div>`).join('')}${r.exercises.length>3?`<details><summary>${r.exercises.length-3} weitere Übungen</summary>${r.exercises.slice(3).map(e=>`<p>${esc(exerciseBookItem(e.exerciseId)?.name||'Übung')} · ${e.sets} Sätze</p>`).join('')}</details>`:''}<div class="actionrow"><button class="btn" onclick="startRoutine('${r.id}')">Starten →</button><button class="textbtn" onclick="deleteRoutine('${r.id}')">Löschen</button></div></section>`).join('')||'<section class="card empty"><p>Erstelle deine erste eigene Routine.</p><button class="btn" onclick="routineForm()">＋ Routine</button></section>'}`};
const flowFinish=finishWorkout;finishWorkout=function(id){let w=state.workouts.find(x=>x.id===id);if(!w||w.finished)return;if(!loggedSets(w).length){toast('Schließe zuerst einen Satz ab');return}let unchecked=w.exercises.reduce((a,e)=>a+e.sets.filter(s=>!s.done).length,0);openModal('Workout abschließen',`<form onsubmit="confirmWorkoutFinish(event,'${w.id}')"><h3>${esc(w.name)}</h3><p>${loggedSets(w).length} absolvierte Sätze${unchecked?' · '+unchecked+' nicht abgehakte Sätze':''}</p>${unchecked?'<p class="note">Nicht abgehakte Sätze werden beim Abschließen verworfen. Bei „Zurück“ kannst du sie weiter bearbeiten.</p>':''}<label>Körpergewicht nach dem Training · kg (optional)<input id="finish-bodyweight" type="number" min="20" max="400" step="0.1" inputmode="decimal" placeholder="z. B. 84"></label><p class="note">Ein eingegebener Wert ersetzt den Gewichtseintrag dieses Trainingstags.</p><button class="btn full">Weiter · Workout abschließen</button><button type="button" class="btn secondary full" onclick="modal.close()">Zurück zum Training</button></form>`)};
function confirmWorkoutFinish(event,id){event.preventDefault();let w=state.workouts.find(x=>x.id===id),raw=$('finish-bodyweight').value,kg=Number(raw);if(!w||w.finished)return;if(raw&&(!Number.isFinite(kg)||kg<20||kg>400)){toast('Bitte ein Gewicht zwischen 20 und 400 kg eingeben');return}for(let e of w.exercises)e.sets=e.sets.filter(s=>s.done);if(raw){w.bodyweight=kg;state.weights=state.weights.filter(x=>x.date!==w.date);state.weights.push({id:uid(),date:w.date,kg})}modal.close();sessionWorkoutId=null;flowFinish(id);save();render()}
function dailyWorkoutStreak(){let days=new Set(completedWorkouts().map(w=>w.date)),d=new Date(today()+'T12:00:00');if(!days.has(localISO(d)))d.setDate(d.getDate()-1);let n=0;while(days.has(localISO(d))){n++;d.setDate(d.getDate()-1)}return n}
function weekWorkoutDots(){let start=new Date(weekStart(today())+'T12:00:00'),days=new Set(completedWorkouts().map(w=>w.date));return `<div class="weekdots">${['Mo','Di','Mi','Do','Fr','Sa','So'].map((label,i)=>{let d=new Date(start);d.setDate(d.getDate()+i);let key=localISO(d);return `<div><small>${label}</small><span class="${days.has(key)?'trained':''} ${key===today()?'todaydot':''}">${days.has(key)?'✓':'·'}</span></div>`}).join('')}</div>`}
function completionHtml(id,step){let w=state.workouts.find(x=>x.id===id),s=workoutStats([w]),award=workoutAwards()[id]||{xp:0,wins:[]},total=Object.values(workoutAwards()).reduce((a,x)=>a+x.xp,0);return `<div class="completion"><button class="quiet completionclose" aria-label="Abschluss schließen" onclick="minimizeSession()">✕</button>${step===0?`<div class="celebration" aria-hidden="true">✦</div><h1>Stark gemacht!</h1><p>${esc(w.name)}</p><div class="completiontiles"><div><small>Dauer</small><strong>${w.durationSeconds==null?'–':formatClock(w.durationSeconds)}</strong></div><div><small>Fortschritt</small><strong>＋${award.xp} XP</strong></div><div><small>Volumen</small><strong>${n(s.volume)} kg</strong></div><div><small>Wiederholungen</small><strong>${s.reps}</strong></div></div><p>${s.sets} Sätze · ${w.exercises.filter(e=>e.sets.length).length} Übungen${w.bodyweight?' · '+n(w.bodyweight)+' kg Körpergewicht':''}</p>${award.wins.map(x=>`<p class="recordwin">↑ Bestleistung · ${esc(x)}</p>`).join('')}`:step===1?`<div class="streakhero">${dailyWorkoutStreak()} 🔥</div><h1>Deine Trainingsserie</h1><p>Aufeinanderfolgende Trainingstage · heutiger oder gestriger letzter Tag</p>${weekWorkoutDots()}<p>${trainingStreak()} Wochen mit mindestens einem Workout. Ruhetage gehören zum Training.</p>`:`<div class="celebration">✧</div><h1>Dein Fortschritt</h1><h2>Level ${1+Math.floor(total/250)}</h2><strong class="xpaward">＋${award.xp} XP</strong><div class="completionxp"><i style="width:${total%250/250*100}%"></i></div><p>${total%250} / 250 XP bis zum nächsten Level · ${total} XP insgesamt</p><details><summary>XP-Aufschlüsselung</summary><p>25 XP pro verbesserter Übung. Erstes Training setzt die Basis; Wiederholungen derselben Leistung bringen keine zusätzlichen Punkte.</p>${award.wins.map(x=>`<p>${esc(x)} · 25 XP</p>`).join('')}</details>`}<button class="btn full completioncontinue" onclick="${step<2?`completionStep=${step+1};renderWorkoutSession()`:'minimizeSession();trainTab=\'current\';go(\'workout\')'}">${step<2?'Weiter':'Fertig ✓'}</button></div>`}
workoutSummary=function(id){let w=state.workouts.find(x=>x.id===id);if(!w?.finished)return;modal.close();$('toast').style.display='none';completionId=id;completionStep=0;sessionWorkoutId=null;renderWorkoutSession()};
const flowIdentity=workoutIdentity;workoutIdentity=function(){return flowIdentity().replace('🔥 '+trainingStreak(),'🔥 '+dailyWorkoutStreak()).replace('Wochenserie','Tageserie')};
const flowRender=render;render=function(){flowRender();let track=$('nutrition-track');if(track){track.scrollLeft=nutrientSlide*track.clientWidth;syncNutritionHeight(track)}renderWorkoutSession()};
const flowValid=validData;validData=function(s){return flowValid(s)&&s.foods.every(x=>validNutrients(x.nutrients))&&s.custom.every(x=>validNutrients(x.nutrients))&&s.workouts.every(w=>w.bodyweight===undefined||Number.isFinite(w.bodyweight)&&w.bodyweight>=20&&w.bodyweight<=400)&&(s.microGoals===undefined||validNutrients(s.microGoals))&&(s.waterGoal===undefined||Number.isFinite(s.waterGoal)&&s.waterGoal>=0&&s.waterGoal<=10000)};render();


const flowQuickTraining=quickTraining;quickTraining=function(){let w=activeWorkout(),html=flowQuickTraining();return w?html.replace("trainTab='current';go('workout')",`openWorkoutSession('${w.id}')`):html};
const flowWorkoutPage=workoutPage;workoutPage=function(){if(trainTab!=='current')return flowWorkoutPage();let active=activeWorkout(),finished=state.workouts.filter(w=>w.finished&&w.date===date);return `<button class="textbtn restglobal" onclick="globalRestSettings()">◷ Standardpause ${formatClock(state.workoutSettings.restSeconds)} · Einstellen</button><div class="tabs workouttabs">${[['current','Workout'],['routines','Routinen'],['calendar','Kalender'],['insights','Fortschritt']].map(([k,label])=>`<button class="btn ${k==='current'?'':'secondary'}" onclick="trainTab='${k}';render()">${label}</button>`).join('')}</div>${active?workoutCard(active):''}${routinesPage()}${finished.length?'<h3>Abgeschlossen · '+fmtDate(date)+'</h3>'+finished.map(workoutCard).join(''):''}<button class="btn secondary full" onclick="startWorkout()">＋ Leeres Workout starten</button>`};
window.addEventListener('resize',()=>syncNutritionHeight($('nutrition-track')));
const flowOffProduct=mapOffProduct;mapOffProduct=function(p,code){let x=flowOffProduct(p,code),ns=p.nutriments||{},meta={};for(let [key,field,factor] of [['fiber','fiber',1],['vitc','vitamin-c',1000],['calcium','calcium',1000],['iron','iron',1000],['b12','vitamin-b12',1000000],['potassium','potassium',1000],['magnesium','magnesium',1000],['folate','folates',1000000]]){let raw=ns[field+'_100g'];if(raw!==undefined&&raw!==null&&raw!==''&&Number.isFinite(+raw)&&+raw>=0)meta[key]=+raw*factor}if(Object.keys(meta).length)x.nutrients=meta;return x};

render();

const readableWorkoutCard=workoutCard;workoutCard=function(w){return readableWorkoutCard(w).replace(/\b1 Sätze/g,'1 Satz').replace(/\b1 Übungen/g,'1 Übung')};
const readableRoutines=routinesPage;routinesPage=function(){return readableRoutines().replace(/\b1 Sätze/g,'1 Satz').replace(/\b1 Übungen/g,'1 Übung')};
const readableCompletion=completionHtml;completionHtml=function(id,step){return readableCompletion(id,step).replace(/\b1 Sätze/g,'1 Satz').replace(/\b1 Übungen/g,'1 Übung').replace(/\b1 Wochen/g,'1 Woche')};render();

const flowAccount=accountPage;accountPage=function(){return flowAccount().replace('Version 12','Version 15')};render();
/* PULS 16 · compact daily experience */
macroCard=function(){return `<section class="card slimenergy"><h2>Energie & Makros</h2>${macroProgress('kcal','Gegessen / Tagesziel','var(--lime)')}<div class="slimmacros">${macroProgress('p','Protein','#8bd4a0')}${macroProgress('c','Kohlenhydrate','#81cbdc')}${macroProgress('f','Fett','#f5ac84')}</div></section>`};
function referenceMicros(){let age=state.profile?.age;if(!age||age<18)return null;return {fiber:30,vitc:110,iron:11,calcium:age<19?1200:1000,b12:4,folate:300,potassium:4000,magnesium:350}}
function microBars(){let nt=nutrientTotals(),refs=referenceMicros();return `<div class="microgrid">${Object.entries(nutrientLabels).map(([k,[label,unit]])=>{let goal=state.microGoals?.[k]||refs?.[k],value=nt.totals[k],known=nt.coverage[k];return `<div><span>${label}</span><strong>${known?n(round(value))+' '+unit:'Keine Werte'}${goal?' / '+n(goal):''}</strong><div class="bar"><i style="width:${goal&&known?Math.min(100,value/goal*100):0}%;background:var(--lime)"></i></div><small>${known}/${nt.count} Einträge mit Wert</small></div>`}).join('')}</div><p class="note">${refs?'DGE/ÖGE-Referenzwerte für gesunde erwachsene Männer; Alter berücksichtigt. Keine Formel aus Kraft oder Gewicht.':'Für Referenzziele bitte das Alter im Profil ergänzen.'} Fehlende Daten sind unbekannt.</p><div class="cardhead"><a class="textbtn" href="https://www.dge.de/wissenschaft/referenzwerte/naehrstofftabelle/" target="_blank" rel="noopener">Referenzwerte ↗</a><button class="textbtn" onclick="microTargetForm()">Eigene Ziele</button></div>`}
nutritionSlides=function(){return `<section class="nutritiondeck"><div class="nutritiontrack" id="nutrition-track" onscroll="nutritionSlideChanged(this)"><article class="nutritionslide"><h2>Energie</h2>${macroProgress('kcal','Gegessen / Tagesziel','var(--lime)')}<p class="note">Kalorienziel ${state.plan.mode==='auto'?'aus deinem Profil':'selbst eingestellt'}</p></article><article class="nutritionslide"><h2>Makros</h2>${macroProgress('p','Protein','#8bd4a0')}${macroProgress('c','Kohlenhydrate','#81cbdc')}${macroProgress('f','Fett','#f5ac84')}</article><article class="nutritionslide"><h2>Mikronährstoffe</h2>${microBars()}</article></div><div class="slidedots">${['Energie','Makros','Mikros'].map((s,i)=>`<button aria-label="${s} anzeigen" class="${nutrientSlide===i?'selected':''}" onclick="setNutrientSlide(${i})"></button>`).join('')}</div></section>`};
syncNutritionHeight=function(){};
const compactFoodPage=nutrition;nutrition=function(){return nutritionSlides()+compactFoodPage().replace(nutrientDetails(),'')};
function weeklyWeights(){let weeks=new Map();for(let w of state.weights){let key=weekStart(w.date);if(!weeks.has(key))weeks.set(key,[]);weeks.get(key).push(w.kg)}return [...weeks].sort((a,b)=>b[0].localeCompare(a[0])).map(([day,values])=>({day,kg:values.reduce((a,b)=>a+b,0)/values.length,count:values.length}))}
function weeklyWeightCard(){let rows=weeklyWeights(),b=bodyMetrics();return `<section class="card compactbody"><div class="cardhead"><h2>Körper & Entwicklung</h2><button class="textbtn" onclick="weightForm()">＋ Gewicht</button></div><div class="bodystrip"><span>Aktuell <strong>${currentWeight()?n(currentWeight())+' kg':'–'}</strong></span><span>BMI <strong>${b?n(round(b.bmi)):'–'}</strong></span><span>Körperfett ≈ <strong>${b?.bf?n(round(b.bf))+' %':'–'}</strong></span></div><p class="note">Körperfett grob aus BMI und Alter geschätzt, keine Messung.</p><h3>Dein Gewicht · Wochenmittel</h3>${rows.slice(0,4).map((r,i)=>`<div class="weekweight"><span>Woche ab ${fmtDate(r.day)}<small>${r.count} Messungen</small></span><strong>${n(round(r.kg))} kg</strong><span>${rows[i+1]?n(round(r.kg-rows[i+1].kg))+' kg':'–'}</span></div>`).join('')||'<p class="note">Deine Gewichtseinträge erscheinen hier als Wochendurchschnitt.</p>'}<details><summary>Alle Wochen</summary>${rows.slice(4).map(r=>`<p>${fmtDate(r.day)} · ${n(round(r.kg))} kg · ${r.count} Messungen</p>`).join('')||'<p class="note">Noch keine weiteren Wochen.</p>'}</details></section>`}
accountPage=function(){let p=state.profile,erhalt=p&&!profileError(p)?Math.round(energyFor({...p,weight:currentWeight()||p.weight}).tdee):null;return `<div class="dashboardstack accountcompact"><div class="accountidentity"><label class="avatarpicker profileavatar" title="Profilbild ändern">${state.avatarImage?`<img src="${state.avatarImage}" alt="Profilbild">`:esc((state.displayName?.trim()||'P')[0])}<span>✎</span><input type="file" accept="image/jpeg,image/png,image/webp" onchange="saveAvatarFile(this.files[0])" aria-label="Profilbild ändern"></label><button class="textbtn accountname" onclick="nameProfile()"><strong>${esc(state.displayName?.trim()||'Nutzername wählen')} ✎</strong><small>${esc(state.email||'E-Mail ergänzen')}</small></button></div><section class="card"><h3>Deine Farben</h3><div class="themeselect">${Object.entries(colorThemes).map(([k,t])=>`<button class="themechoice" aria-pressed="${(state.colorTheme||'purple')===k}" onclick="chooseColorTheme('${k}')"><i style="background:${t.accent}"></i>${t.name}</button>`).join('')}</div></section>${weeklyWeightCard()}<section class="card compactplan"><div class="cardhead"><h2>Dein Plan</h2><button class="textbtn" onclick="settings()">Plan anpassen ↗</button></div><dl><dt>Kalorienziel</dt><dd>${n(state.goals.kcal)} kcal</dd><dt>Geschätzter Erhalt</dt><dd>${erhalt?n(erhalt)+' kcal':'Profil ergänzen'}</dd><dt>Zielszenario</dt><dd>${({lose:'Fett abnehmen',gain:'Muskeln aufbauen',maintain:'Gewicht halten'})[state.plan.direction]||'Selbst festgelegt'}${p?' · '+n(p.target)+' kg':''}</dd><dt>Aktuelles Gewicht</dt><dd>${currentWeight()?n(currentWeight())+' kg':'–'}</dd></dl></section><section class="card"><h3>Deine Daten</h3><p class="note">Lokales Profil auf diesem Gerät. Die E-Mail wird nicht geprüft. Kein Login und keine Cloud-Synchronisierung.</p><div class="actionrow"><button class="btn secondary" onclick="exportData()">Sicherung</button><button class="textbtn" onclick="settings();dataSettings()">Daten & Methoden</button></div><small>PULS · Version 16</small></section></div>`};
let setupPending=false;
nameProfile=function(){openModal(setupPending?'Willkommen bei PULS':'Dein Profil',`<form onsubmit="saveNameProfile(event)"><p class="note">${setupPending?'1 · Dein Profil → 2 · Deine Ziele':'Dein Profil bleibt auf diesem Gerät.'}</p><label>Nutzername<input id="profile-name" maxlength="40" required autocomplete="nickname" value="${esc(state.displayName||'')}"></label><label>E-Mail<input id="profile-email" type="email" maxlength="254" required autocomplete="email" value="${esc(state.email||'')}"></label><label>Profilbild (optional)<input type="file" accept="image/jpeg,image/png,image/webp" onchange="saveAvatarFile(this.files[0])"></label><p class="note">Ohne Passwort. Keine E-Mail-Verifizierung oder Synchronisierung.</p><button class="btn full">${setupPending?'Weiter zu deinen Zielen':'Profil speichern'}</button></form>`)};
saveNameProfile=function(e){e.preventDefault();let name=$('profile-name').value.trim(),email=$('profile-email').value.trim();if(!name||name.length>40||!email||email.length>254||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){toast('Bitte Nutzername und gültige E-Mail eingeben');return}state.displayName=name;state.email=email;if(setupPending)state.setupPending=true;save();modal.close();if(setupPending){state.plan.mode='auto';settings()}else render()};
const refinedProfileForm=profileForm;profileForm=function(){refinedProfileForm();let select=$('pl-direction');for(let option of select.options)option.textContent=({lose:'Fett abnehmen',gain:'Muskeln aufbauen',maintain:'Gewicht halten'})[option.value]||option.textContent};
function finishOnboarding(){state.setupPending=false;state.onboardingComplete=true;setupPending=false;save();modal.close();go('home')}
function needsOnboarding(){return !!state.setupPending||(!state.onboardingComplete&&!state.displayName?.trim()&&!state.profile)}
const onboardingImportBase=importData;importData=async function(file){let before=state;await onboardingImportBase(file);if(state!==before){setupPending=needsOnboarding();if(setupPending){if(state.setupPending)settings();else nameProfile()}}};
// Only first-run setup may skip incomplete or unsupported planning inputs.
const refinedCommit=commitProfile;commitProfile=function(e){if(!setupPending)return refinedCommit(e);e.preventDefault();let before=state.profile,p=collectProfile(),pl={...collectPlan(),mode:'auto'};if(!profileError(p)&&validData({...state,profile:p,plan:pl})){$('pl-mode').value='auto';refinedCommit(e)}if(state.profile===before)$('plan-error').textContent='';finishOnboarding()};
const onboardingProfileForm=profileForm;profileForm=function(){onboardingProfileForm();if(setupPending){let form=$('planner-form');form.noValidate=true;form.insertAdjacentHTML('afterbegin','<p class="note">Alle Angaben sind optional. Ohne vollständige, gültige Angaben erfolgt keine automatische Kalorienberechnung. Du kannst dein Profil später im Konto ergänzen.</p>');form.querySelector('button.btn.full').textContent='Weiter zur Übersicht';updatePlanPreview()}};
const onboardingPlanPreview=updatePlanPreview;updatePlanPreview=function(){onboardingPlanPreview();if(setupPending&&profileError(collectProfile())){$('plan-error').textContent='';$('plan-preview').innerHTML='<p class="note">Ohne vollständiges Profil bleiben deine bisherigen Tagesziele erhalten.</p>'}};
const refinedRender=render;render=function(){refinedRender();let top=$('workout-identity'),bar=document.querySelector('.datebar');if(top){top.hidden=page==='account';top.innerHTML=page==='account'?'':workoutIdentity()}if(bar)bar.hidden=page==='account'};
const refinedValid=validData;validData=function(s){return refinedValid(s)&&(s.email===undefined||typeof s.email==='string'&&s.email.length<=254)&&(s.setupPending===undefined||typeof s.setupPending==='boolean')&&(s.onboardingComplete===undefined||typeof s.onboardingComplete==='boolean')};
render();
if(needsOnboarding()){setupPending=true;if(state.setupPending)settings();else nameProfile()}
modal.addEventListener('cancel',e=>{if(setupPending)e.preventDefault()});
const weeklyTrendBase=trendData;trendData=function(){let data=weeklyTrendBase(),weeks=weeklyWeights();return data.map(x=>({...x,weight:weeks.find(w=>w.day===weekStart(x.date))&&new Date(x.date+'T12:00:00').getDay()===1?weeks.find(w=>w.day===weekStart(x.date)).kg:null}))};
const weeklyProgressBase=progressChart;progressChart=function(){return weeklyProgressBase().replace('● Gewicht','● Gewicht · Wochenmittel').replace('Vergleichsindex:','Gewicht: Mittelwert der erfassten Messungen pro Kalenderwoche. Vergleichsindex:')};
modal.addEventListener('close',()=>{if(setupPending)setTimeout(()=>{if(setupPending&&!modal.open){if(state.setupPending)settings();else nameProfile()}},0)});
const balancedSlides=nutritionSlides;nutritionSlides=function(){let t=totals(),g=state.goals.kcal||0;return balancedSlides().replace(`<h2>Energie</h2>${macroProgress('kcal','Gegessen / Tagesziel','var(--lime)')}<p class="note">Kalorienziel ${state.plan.mode==='auto'?'aus deinem Profil':'selbst eingestellt'}</p>`,`<h2>Energie</h2><div class="caloriedial" style="--fill:${g?Math.min(100,t.kcal/g*100):0}%"><div><strong>${n(Math.round(t.kcal))}</strong><small>von ${n(g)} kcal</small></div></div><p class="energycaption">${t.kcal>g?n(Math.round(t.kcal-g))+' kcal über Ziel':n(Math.round(g-t.kcal))+' kcal übrig'}</p>`)};
render();
trendData=function(){let data=weeklyTrendBase(),weeks=weeklyWeights();return data.map(x=>{let week=weekStart(x.date),last=state.weights.filter(w=>weekStart(w.date)===week&&w.date<=today()).map(w=>w.date).sort().at(-1);return {...x,weight:x.date===last?weeks.find(w=>w.day===week)?.kg??null:null}})};
/* PULS 17: compact nutrition carousel and explicit calorie allowance. */
const allowanceMacroCard=macroCard;macroCard=function(){let t=totals(),left=Math.max(0,state.goals.kcal-t.kcal);return allowanceMacroCard().replace('<div class="slimmacros">',`<div class="calorieallowance"><strong>${n(Math.round(left))} kcal</strong><span>${t.kcal>state.goals.kcal?'übrig · '+n(Math.round(t.kcal-state.goals.kcal))+' kcal über Ziel':'kannst du heute noch essen'}</span></div><div class="slimmacros">`)};
const detailedMicroBars=microBars;microBars=function(){let nt=nutrientTotals(),refs=referenceMicros();return `<div class="microgrid compactmicros">${Object.entries(nutrientLabels).map(([k,[label,unit]])=>{let goal=state.microGoals?.[k]||refs?.[k],known=nt.coverage[k],value=nt.totals[k];return `<div title="${known}/${nt.count} Einträge mit Wert"><div class="microlabel"><span>${label}</span><strong>${known?(goal?Math.round(value/goal*100)+' %':n(round(value))+' '+unit):'–'}</strong></div><div class="bar"><i style="width:${known&&goal?Math.min(100,value/goal*100):0}%;background:var(--lime)"></i></div></div>`}).join('')}</div>`};
const compactNutritionPage=nutrition;nutrition=function(){return compactNutritionPage()+`<details class="card"><summary>Nährstoffwerte & Ziele im Detail</summary>${detailedMicroBars()}</details>`};
const release17Account=accountPage;accountPage=function(){return release17Account().replace('Version 16','Version 17')};render();
/* PULS 18: identical combined nutrition card on home and diary. */
function combinedNutrition(){let t=totals(),goal=state.goals.kcal||0,left=Math.max(0,goal-t.kcal);return `<h2>Energie & Makros</h2><div class="combinednutrition"><div class="caloriedial" style="--fill:${goal?Math.min(100,t.kcal/goal*100):0}%"><div><strong>${n(Math.round(t.kcal))}</strong><small>von ${n(goal)} kcal</small></div></div><div class="combinedbars">${macroProgress('p','Protein','#8bd4a0')}${macroProgress('c','Kohlenhydrate','#81cbdc')}${macroProgress('f','Fett','#f5ac84')}</div></div><p class="combinedallowance"><strong>${n(Math.round(left))} kcal</strong> ${t.kcal>goal?'übrig · '+n(Math.round(t.kcal-goal))+' kcal über Ziel':'kannst du noch essen'}</p>`}
nutritionSlides=function(){return `<section class="nutritiondeck"><div class="nutritiontrack" id="nutrition-track" onscroll="nutritionSlideChanged(this)"><article class="nutritionslide">${combinedNutrition()}</article><article class="nutritionslide"><h2>Mikronährstoffe</h2>${microBars()}</article></div><div class="slidedots">${['Energie & Makros','Mikros'].map((label,i)=>`<button aria-label="${label} anzeigen" class="${nutrientSlide===i?'selected':''}" onclick="setNutrientSlide(${i})"></button>`).join('')}</div></section>`};
macroCard=function(){return nutritionSlides()};
setNutrientSlide=function(i){nutrientSlide=Math.max(0,Math.min(1,i));let track=$('nutrition-track');if(track)track.scrollTo({left:nutrientSlide*track.clientWidth,behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})};
nutritionSlideChanged=function(track){nutrientSlide=Math.max(0,Math.min(1,Math.round(track.scrollLeft/Math.max(1,track.clientWidth))));document.querySelectorAll('.slidedots button').forEach((el,i)=>el.classList.toggle('selected',i===nutrientSlide))};
const release18Account=accountPage;accountPage=function(){return release18Account().replace('Version 17','Version 18')};nutrientSlide=0;render();
/* PULS 19: personal profile, routine rotation and flexible trends. */
if(state.email!==undefined){delete state.email;save()}
nameProfile=function(){openModal(setupPending?'Willkommen bei PULS':'Dein Profil',`<form onsubmit="saveNameProfile(event)"><label>Nutzername${setupPending?' (optional)':''}<input id="profile-name" maxlength="40" ${setupPending?'':'required'} autocomplete="nickname" value="${esc(state.displayName||'')}"></label><label>Profilbild (optional)<input type="file" accept="image/jpeg,image/png,image/webp" onchange="saveAvatarFile(this.files[0])"></label><p class="note">${setupPending?'Alle Angaben sind optional. Du kannst sie später im Konto ergänzen.':'Dein Profil bleibt auf diesem Gerät.'}</p><button class="btn full">${setupPending?'Weiter zu deinen Zielen':'Profil speichern'}</button></form>`)};
saveNameProfile=function(e){e.preventDefault();let name=$('profile-name').value.trim();if((!name&&!setupPending)||name.length>40)return;state.displayName=name;if(setupPending)state.setupPending=true;save();modal.close();if(setupPending)settings();else render()};
function planTargetDate(){let p=state.profile;if(!p||profileError(p))return 'Profil ergänzen';let current=currentWeight()||p.weight;if((state.plan.direction==='lose'&&current<=p.target)||(state.plan.direction==='gain'&&current>=p.target)||Math.abs(current-p.target)<.05)return 'Zielgewicht erreicht';let days=forecastDays(current,p.target,energyFor({...p,weight:current}).tdee,state.goals.kcal);return days===null?'Mit diesem Plan kein belastbarer Termin':dateAfter(days)}
const account19=accountPage;accountPage=function(){return account19().replace(`<small>${esc(state.email||'E-Mail ergänzen')}</small>`,'').replace('Die E-Mail wird nicht geprüft. ','').replace('</dl>',`<dt>Zielgewicht voraussichtlich</dt><dd>${esc(planTargetDate())}</dd></dl><p class="note">Modellschätzung ab heute bei konstanten Kalorien; tatsächlicher Verlauf kann abweichen.</p>`).replace('<small>PULS · Version 18</small>','<div class="versionstamp">PULS <span>Version 19</span></div>')};
function routineRecommendation(){let last=completedWorkouts().slice().sort((a,b)=>b.date.localeCompare(a.date)||(b.startedAt||0)-(a.startedAt||0))[0],index=last?state.routines.findIndex(r=>r.id===last.routineId||r.name===last.name):-1;return {last,next:state.routines.length?state.routines[(index+1)%state.routines.length]:null}}
function recommendedPreview(r){return `<div class="recommendedroutine"><div class="cardhead"><div><h2>${esc(r.name)}</h2><small>${r.exercises.length} Übungen · ${r.exercises.reduce((a,e)=>a+e.sets,0)} Sätze</small></div><span class="badge">Als Nächstes</span></div>${r.exercises.slice(0,3).map(e=>`<div class="routinepreviewrow"><span>${esc(exerciseBookItem(e.exerciseId)?.name||'Übung')}</span><small>${e.sets} Sätze</small></div>`).join('')}${r.exercises.length>3?`<details><summary>${r.exercises.length-3} weitere Übungen</summary>${r.exercises.slice(3).map(e=>`<p>${esc(exerciseBookItem(e.exerciseId)?.name||'Übung')} · ${e.sets} Sätze</p>`).join('')}</details>`:''}<button class="btn full" onclick="startRoutine('${r.id}')">${esc(r.name)} starten →</button></div>`}
quickTraining=function(){let active=activeWorkout(),{last,next}=routineRecommendation();return `<section class="card"><div class="cardhead"><h2>Training starten</h2><button class="textbtn" onclick="trainTab='routines';go('workout')">Alle Routinen ↗</button></div>${active?`<button class="btn full" onclick="openWorkoutSession('${active.id}')">${esc(active.name)} fortsetzen →</button>`:`${last?`<p class="note">Zuletzt: ${esc(last.name)} · ${fmtDate(last.date)}</p>`:''}${next?recommendedPreview(next)+'<p class="note">Vorschlag nach der Reihenfolge deiner Routinen. Ruhetage kannst du frei wählen.</p>':'<button class="btn full" onclick="routineForm()">＋ Routine erstellen</button>'}`}</section>`};
const periods19={week:'Woche',month:'Monat',half:'Halbjahr',year:'Jahr',all:'Gesamt'};
function setChartPeriod(v){if(!periods19[v])return;state.chartPeriod=v;save();render()}
function toggleChartLine(k){state.chartLines??={};state.chartLines[k]=state.chartLines[k]===false;save();render()}
function allChartLines(){state.chartLines={weight:true,strength:true,kcal:true};save();render()}
const chart19=progressChart;progressChart=function(){let period=periods19[state.chartPeriod]||'Monat';return chart19().replace('<span class="badge">90 Tage</span>',`<label class="chartperiod">Zeitraum<select aria-label="Zeitraum für Gesamtfortschritt" onchange="setChartPeriod(this.value)">${Object.entries(periods19).map(([k,v])=>`<option value="${k}" ${(state.chartPeriod||'month')===k?'selected':''}>${v}</option>`).join('')}</select></label>`).replace('<div class="trendlegend">',`<div class="charttoggles">${[['weight','Gewicht','#a3b9fb'],['strength','Kraft','#c3f86b'],['kcal','Kalorien','#f2b87d']].map(([k,label,c])=>`<button aria-pressed="${state.chartLines?.[k]!==false}" style="--series:${c}" onclick="toggleChartLine('${k}')">● ${label}</button>`).join('')}<button onclick="allChartLines()">Alle an</button></div><div class="trendlegend">`).replace('Erfasse Gewicht, Essen und Trainings.',Object.values(state.chartLines||{}).filter(v=>v===false).length===3?'Alle Kurven ausgeblendet. Wähle oben eine Kurve aus.':'Erfasse Gewicht, Essen und Trainings.')};
render();if(setupPending&&!state.setupPending)nameProfile();
const spacedAnalytics=analyticsPage;analyticsPage=function(){return '<div class="analyticsstack">'+spacedAnalytics()+'</div>'};
const singularRecommendation=recommendedPreview;recommendedPreview=function(r){return singularRecommendation(r).replace(/\b1 Sätze/g,'1 Satz').replace(/\b1 Übungen/g,'1 Übung')};
/* PULS 20: optional visual styles; structure and workout flows stay intact. */
const appDesigns={classic:{name:'PULS Original',note:'Dein bisheriges Design',bg:'#121015',panel:'#1d1923',line:'#493354',accent:'#c7a0ff',tint:'#352345',ink:'#f0edf5',muted:'#aaa3b4',radius:'16px'},apple:{name:'Apple',note:'Ruhig · weich · Glas',bg:'#080809',panel:'#1c1c1e',line:'#38383b',accent:'#82b7ff',tint:'#192d46',ink:'#f5f5f7',muted:'#a1a1a9',radius:'22px'},cronometer:{name:'Cronometer',note:'Schiefer · Orange · klare Linien',bg:'#1c1e2b',panel:'#272a3a',line:'#414453',accent:'#ff9b76',tint:'#44352f',ink:'#f5f4fa',muted:'#b3b4c4',radius:'12px'},liftoff:{name:'Liftoff',note:'Bordeaux · Pink · warmes Creme',bg:'#160707',panel:'#290d14',line:'#572021',accent:'#f04ba1',tint:'#481817',ink:'#fff1bd',muted:'#d6b995',radius:'18px'},hevy:{name:'Hevy',note:'Schwarz · Blau · sportlich',bg:'#090b0e',panel:'#171b21',line:'#30353e',accent:'#62afff',tint:'#142f4c',ink:'#f7f8fa',muted:'#a4aebb',radius:'10px'},aurora:{name:'Aurora',note:'Nachtblau · Türkis · sanftes Licht',bg:'#07191e',panel:'#102b33',line:'#27505b',accent:'#74e4d2',tint:'#173e43',ink:'#e5faf7',muted:'#a0c0c3',radius:'20px'},mono:{name:'Graphit',note:'Reduziert · monochrom · präzise',bg:'#101010',panel:'#202020',line:'#424242',accent:'#eeeeee',tint:'#343434',ink:'#f4f4f4',muted:'#b0b0b0',radius:'5px'}};
function designChooser(){let selected=state.appDesign||'classic';return `<section class="card designchooser"><div class="cardhead"><h2>Dein Design</h2><span class="badge">7 Varianten</span></div><p class="note">Die Vorbilder als Stilvarianten für PULS. Aufbau und Funktionen bleiben gleich.</p><div class="designoptions">${Object.entries(appDesigns).map(([key,d])=>`<button class="designoption" aria-pressed="${selected===key}" onclick="chooseAppDesign('${key}')" aria-label="Design ${d.name}"><span class="designmini designmini-${key}" style="--sample-bg:${d.bg};--sample-panel:${d.panel};--sample-line:${d.line};--sample-accent:${d.accent};--sample-radius:${d.radius}"><i></i><span><b></b><b></b><b></b></span><em></em></span><span class="designcaption"><strong>${d.name}${selected===key?' ✓':''}</strong><small>${d.note}</small></span></button>`).join('')}</div><p class="note">Original verwendet deine Farbauswahl. Die anderen Designs haben jeweils eine eigene Palette.</p></section>`}
function chooseAppDesign(key){if(!Object.hasOwn(appDesigns,key))return;state.appDesign=key;save();render();toast(appDesigns[key].name+' aktiviert')}
function applyAppDesign(){let key=Object.hasOwn(appDesigns,state.appDesign)?state.appDesign:'classic',d=appDesigns[key],content=$('content');if(!content)return;content.dataset.design=key;let base=colorThemes[state.colorTheme]||colorThemes.purple;for(let [k,v] of Object.entries({'--bg':key==='classic'?base.bg:d.bg,'--panel':key==='classic'?base.surface:d.panel,'--line':key==='classic'?base.line:d.line,'--lime':key==='classic'?base.accent:d.accent,'--theme-tint':key==='classic'?base.tint:d.tint,'--design-ink':d.ink,'--design-muted':d.muted,'--design-radius':d.radius}))content.style.setProperty(k,v);content.querySelectorAll?.('.nutritiondeck,.accountidentity').forEach(el=>{for(let [k,v] of Object.entries({'--bg':base.bg,'--panel':base.surface,'--line':base.line,'--lime':base.accent,'--theme-tint':base.tint}))el.style.setProperty(k,v)})}
const designAccountBase=accountPage;accountPage=function(){return designAccountBase().replace('<section class="card compactbody">',designChooser()+'<section class="card compactbody">').replace('Version 19','Version 20')};
const designRenderBase=render;render=function(){designRenderBase();applyAppDesign()};
const designValidBase=validData;validData=function(s){return designValidBase(s)&&(s.appDesign===undefined||Object.hasOwn(appDesigns,s.appDesign))};render();
/* PULS 21: distinct page compositions, not only palettes. */
function currentDesign(){return Object.hasOwn(appDesigns,state.appDesign)?state.appDesign:'classic'}
appDesigns.apple.note='iOS-Listen · schwebende Aktionen · große Typografie';appDesigns.cronometer.note='Tagebuch zuerst · kompakte Zeilen · Werkzeugleiste';appDesigns.liftoff.note='Trainingsbühne · kräftige Flächen · Spielcharakter';appDesigns.hevy.note='Routine im Fokus · Listen · klare Daten';appDesigns.aurora.note='Dashboard · Lichtflächen · offene Module';appDesigns.mono.note='Editorial · nummerierte Kapitel · Raster';
function designActions(){return `<div class="designactionstrip"><button onclick="foodForm();foodTab('search')"><span>＋</span>Essen eintragen</button><button onclick="foodForm();foodTab('barcode')"><span>▥</span>Scannen</button><button onclick="weightForm()"><span>◎</span>Gewicht</button></div>`}
function designChapter(number,title,body,cls=''){return `<section class="designchapter ${cls}"><div class="chapterlabel"><span>${number}</span><h2>${title}</h2></div>${body}</section>`}
const layoutOriginalHome=home;home=function(){let key=currentDesign();if(key==='classic')return layoutOriginalHome();let energy=nutritionSlides(),actions=designActions(),training=quickTraining(),diary=todayFoodList(),chart=progressChart();if(key==='apple')return `<div class="designhome applehome">${energy}${actions}<div class="applegroup"><div class="designsectionlabel">Dein Training</div>${training}</div><div class="applegroup"><div class="designsectionlabel">Heute erfasst</div>${diary}</div>${chart}</div>`;if(key==='cronometer')return `<div class="designhome journalhome">${energy}${actions}<div class="journalbody">${compactDiary()}</div><div class="journaltraining">${training}</div>${chart}</div>`;if(key==='liftoff')return `<div class="designhome gamehome">${energy}<div class="trainingstage"><div class="designsectionlabel">DEINE NÄCHSTE SESSION</div>${training}</div>${actions}<div class="gamejournal">${diary}</div>${chart}</div>`;if(key==='hevy')return `<div class="designhome athletehome">${energy}<div class="athleteworkout"><div class="designsectionlabel">TRAINING</div>${training}</div>${actions}<div class="activityfeed">${diary}</div>${chart}</div>`;if(key==='aurora')return `<div class="designhome aurorahome">${energy}${actions}<div class="auroramodules"><div class="auroratraining">${training}</div><div class="aurorafood">${diary}</div></div>${chart}</div>`;return `<div class="designhome editorialhome">${energy}${designChapter('01','Ernährung',actions+diary)}${designChapter('02','Training',training)}${designChapter('03','Entwicklung',chart)}</div>`};
const layoutFoodBase=nutrition;nutrition=function(){return `<div class="designdiary">${layoutFoodBase()}</div>`};
const layoutWorkoutBase=workoutPage;workoutPage=function(){return `<div class="designworkouts">${layoutWorkoutBase()}</div>`};
const layoutAccountBase=accountPage;accountPage=function(){return layoutAccountBase().replace('Aufbau und Funktionen bleiben gleich.','Eigene Seitenlayouts und Gestaltung, dieselben Funktionen.').replace('Version 20','Version 21')};
const layoutDesignBase=applyAppDesign;applyAppDesign=function(){layoutDesignBase();let key=currentDesign(),d=appDesigns[key];document.body.dataset.appDesign=key;if(key!=='classic'){let root=document.documentElement;for(let [k,v] of Object.entries({'--bg':d.bg,'--panel':d.panel,'--line':d.line,'--lime':d.accent,'--theme-tint':d.tint,'--muted':d.muted,'--app-ink':d.ink}))root.style.setProperty(k,v)}else document.documentElement.style.setProperty('--muted','#a5afa0')};
const layoutChooseBase=chooseAppDesign;chooseAppDesign=function(key){layoutChooseBase(key);window.scrollTo?.({top:0,behavior:'smooth'})};render();
/* PULS 22: compact controls and five independent visual systems. */
workoutPage=function(){let tabs=`<div class="tabs workouttabs" aria-label="Trainingsbereiche">${[['current','Workout'],['routines','Routinen'],['calendar','Kalender'],['insights','Fortschritt']].map(([k,label])=>`<button class="btn ${trainTab===k?'':'secondary'}" aria-pressed="${trainTab===k}" onclick="trainTab='${k}';render()">${label}</button>`).join('')}</div>`,pause=`<button class="textbtn restglobal" onclick="globalRestSettings()">◷ Standardpause ${formatClock(state.workoutSettings.restSeconds)} · Einstellen</button>`,body='';if(trainTab==='routines')body=routinesPage();else if(trainTab==='calendar')body=trainingCalendar();else if(trainTab==='insights'||trainTab==='records')body=analyticsPage();else{let active=activeWorkout(),finished=state.workouts.filter(w=>w.finished&&w.date===date);body=(active?workoutCard(active):'')+routinesPage()+(finished.length?'<h3>Abgeschlossen · '+fmtDate(date)+'</h3>'+finished.map(workoutCard).join(''):'')+`<button class="btn secondary full" onclick="startWorkout()">＋ Leeres Workout starten</button>`}return `<div class="designworkouts">${tabs}${pause}<div class="workoutbody">${body}</div></div>`};
function addWaterGlass(){state.foods.push({id:uid(),date,meal:'Snacks',name:'Trinkwasser',grams:250,unit:'ml',kcal:0,p:0,c:0,f:0,nutrients:{water:250}});save();render();toast('＋ 250 ml Wasser')}
waterCard=function(){let nt=nutrientTotals(),goal=state.waterGoal||0;return `<section class="card watercompact"><div class="waterinline"><div><h3>💧 Gesamtwasser</h3><strong>${n(Math.round(nt.totals.water))} <small>ml${goal?' / '+n(goal)+' ml':''}</small></strong></div><button class="btn secondary waterglass" onclick="addWaterGlass()">＋ 250 ml</button></div>${goal?`<div class="bar"><i style="width:${Math.min(100,nt.totals.water/goal*100)}%;background:#81cbdc"></i></div>`:''}<div class="waterfoot"><button class="textbtn" onclick="waterGoalForm()">${goal?'Ziel ändern':'Eigenes Ziel setzen'}</button><details><summary>Wasserwerte</summary><p class="note">Bekannter Wasseranteil aus Essen und Getränken · ${nt.coverage.water}/${nt.count} Einträge mit Wert.${nt.unknownDrinks?' '+nt.unknownDrinks+' Getränke ohne Wasserwert.':''} Fehlende Werte sind nicht enthalten.</p></details></div></section>`};
const account22Base=accountPage;accountPage=function(){return account22Base().replace(/<section class="card"><h3>Deine Farben<\/h3>[\s\S]*?<\/section>/,'').replace('</button></div><section',`</button><div class="accountstreak"><strong>🔥 ${dailyWorkoutStreak()}</strong><small>Tageserie</small></div></div><section`).replace('Version 21','Version 22')};
