Object.assign(appDesigns.liftoff,{name:'Forge',note:'Trainingsarena · große Flächen · starke Kontraste',bg:'#140d0b',panel:'#2b1812',line:'#66392a',accent:'#ff975d',tint:'#4b2719',ink:'#fff0db',muted:'#d3b397'});
Object.assign(appDesigns.aurora,{name:'Orbit',note:'Schwebende Module · großer Energiekreis · Türkis',bg:'#07191e',panel:'#102b33',line:'#27505b',accent:'#74e4d2',tint:'#173e43',ink:'#e5faf7',muted:'#a0c0c3'});
