if(state.appDesign==='hevy'){state.appDesign='classic';save()}Object.defineProperty(appDesigns,'hevy',{...Object.getOwnPropertyDescriptor(appDesigns,'hevy'),enumerable:false});
const chooser22Base=designChooser;designChooser=function(){return chooser22Base().replace('7 Varianten','Original + 5').replace('Die Vorbilder als Stilvarianten für PULS. Eigene Seitenlayouts und Gestaltung, dieselben Funktionen.','Fünf eigenständige Oberflächen. Alle Funktionen bleiben verfügbar.').replace('Die Vorbilder als Stilvarianten für PULS. Aufbau und Funktionen bleiben gleich.','Fünf eigenständige Oberflächen. Alle Funktionen bleiben verfügbar.').replace('Original verwendet deine Farbauswahl. Die anderen Designs haben jeweils eine eigene Palette.','Deine Auswahl wird auf diesem Gerät gespeichert. Original bleibt jederzeit verfügbar.')};
applyAppDesign=function(){let key=currentDesign(),d=appDesigns[key],content=$('content');if(!content)return;let base=colorThemes[state.colorTheme]||colorThemes.purple,palette=key==='classic'?{bg:base.bg,panel:base.surface,line:base.line,accent:base.accent,tint:base.tint,ink:'#f0edf5',muted:'#a5afa0'}:d;document.body.dataset.appDesign=key;content.dataset.design=key;let vars={'--bg':palette.bg,'--panel':palette.panel,'--line':palette.line,'--lime':palette.accent,'--theme-tint':palette.tint,'--muted':palette.muted,'--app-ink':palette.ink,'--design-ink':palette.ink,'--design-muted':palette.muted,'--design-radius':d.radius};for(let [k,v] of Object.entries(vars)){document.documentElement.style.setProperty(k,v);content.style.setProperty(k,v)}content.querySelectorAll?.('.nutritiondeck').forEach(el=>{for(let k of ['--bg','--panel','--line','--lime','--theme-tint'])el.style.removeProperty(k)});document.querySelectorAll('#workout-identity,.datebar,aside,.accountidentity').forEach(el=>{for(let [k,v] of Object.entries({'--bg':base.bg,'--panel':base.surface,'--line':base.line,'--lime':base.accent,'--theme-tint':base.tint,'--muted':'#a5afa0'}))el.style.setProperty(k,v);el.style.background=base.bg;el.style.color='#f0edf5'})};render();
